changes.after:
paletteControls.append(help);
paletteControls.id = viewId + '-palette-tools';
const paletteToggle = button('探す・作るをたたむ', 'palette-tools-toggle', () => {
  paletteControls.hidden = !paletteControls.hidden;
  paletteToggle.setAttribute('aria-expanded', String(!paletteControls.hidden));
  paletteToggle.textContent = paletteControls.hidden ? '探す・作るをひらく' : '探す・作るをたたむ';
});
paletteToggle.setAttribute('aria-expanded', 'true');
paletteToggle.setAttribute('aria-controls', paletteControls.id);
const paletteTools = E('div', 'blockui-palette-tools');
paletteTools.append(paletteToggle, paletteControls);
palette.append(paletteTools, categorySelect, paletteList, palettePages);

.blockui-palette-tools { grid-column:1/-1; grid-row:1; min-width:0; width:100%; }
.blockui-palette-controls[hidden] { display:none !important; }
[data-blockui-action="palette-tools-toggle"] { width:100%; flex:none; }
.blockui-local-help { font-size:12px; max-width:100%; }

#runtimeInspector { width:min(1180px,96vw); height:92dvh; max-height:96dvh; box-sizing:border-box; padding:10px; border:1px solid var(--line); border-radius:10px; overflow:hidden; }
#runtimeInspector[open] { display:flex; flex-direction:column; gap:8px; }
#runtimeInspector::backdrop { background:#24344966; }
.runtime-inspector-head { display:flex; flex-wrap:wrap; align-items:center; gap:8px; flex:none; }
#runtimeInspectorModes { margin-left:auto; }
#runtimeInspectorBody { display:grid; grid-template-columns:minmax(0,1fr) 250px; gap:8px; flex:1; min-height:0; overflow:auto; }
#runtimeInspectorBody > .codewin { display:flex !important; min-height:0 !important; min-width:0; overflow:auto; }
#runtimeInspectorBody .debugbar { padding:6px; flex:none; }
#runtimeInspectorBody .editor-shell { flex:1; min-height:160px; }
#runtimeInspectorBody #blockEditor { flex:1; min-height:260px; }
#runtimeInspectorBody .blockui-layout { flex:1; min-height:0 !important; }
#runtimeInspectorBody .monitor-window { display:flex !important; min-height:160px; overflow:auto; }
@media(max-width:700px) { #runtimeInspectorBody { grid-template-columns:minmax(0,1fr); } #runtimeInspectorModes { margin-left:0; } }
.blockui-local-help { font-size:12px; max-width:100%; }

const inspectorNodes = [];
function closeRuntimeInspector() {
  const dialog = $('#runtimeInspector');
  if (dialog.open) dialog.close();
  for (const {node, marker} of inspectorNodes.splice(0)) { marker.replaceWith(node); }
  if (appState === 'RUNNING' || appState === 'PAUSED') {
    stageView.fitStage();
    el.form.focus({ preventScroll: true });
  }
}
function openRuntimeInspector() {
  if (!['RUNNING', 'PAUSED'].includes(appState) || inspectorNodes.length) return;
  stageView.clearInput();
  for (const [node, target] of [[$('.codewin'), $('#runtimeInspectorBody')], [$('.monitor-window'), $('#runtimeInspectorBody')], [$('#editorModecode').parentElement, $('#runtimeInspectorModes')]]) {
    const marker = document.createComment('runtime inspector return point');
    node.before(marker); inspectorNodes.push({node, marker}); target.append(node);
  }
  $('#runtimeInspector').showModal();
  renderEditorBinding(mainEditor);
  $('#runtimeInspectorClose').focus();
}
$('#runtimeInspectBtn').onclick = openRuntimeInspector;
$('#runtimeInspectorClose').onclick = closeRuntimeInspector;
$('#runtimeInspectorStop').onclick = stopRun;
$('#runtimeInspector').addEventListener('close', () => { if (inspectorNodes.length) closeRuntimeInspector(); });
function disposeRuntime() {
  closeRuntimeInspector();

body.runtime[data-editor-mode] .debugbar :is(#pauseBtn,#continueBtn,#stepBtn) { display: inline-flex; }
body.runtime[data-editor-mode] .menutool > :is(#newBtn,#sampleSelect,#sampleBtn,#sampleHelpBtn,#openBtn) { display:none; }
body.runtime[data-editor-mode] .debugbar > :is(#undoBtn,#redoBtn,#formatBtn,#resetBtn) { display:none; }
#runtimeInspector #runtimeInspectBtn { display:none; }
